set-variable.value:
@{
    var result = new JObject(new JProperty("route", "none"), new JProperty("mode", "observe"),
      new JProperty("httpMethod", "unknown"), new JProperty("presence", "unknown"),
      new JProperty("countBucket", "unknown"), new JProperty("duplicates", "unknown"),
      new JProperty("allowed", true), new JProperty("status", 0));
    if (!context.Variables.ContainsKey("gatewayCommonAuthenticationValidated")
        || !(bool)context.Variables["gatewayCommonAuthenticationValidated"]
        || context.Api == null) {
      return result.ToString(Newtonsoft.Json.Formatting.None);
    }
    var operation = context.Operation == null ? "" : context.Operation.Id;
    var path = context.Operation == null ? "" : context.Operation.UrlTemplate;
    var publicPath = context.Request.OriginalUrl.Path;
    var method = context.Request.Method;
    /* 設定で変更できる内部名には依存せず、固定公開pathと選択済み制約を照合します。 */
    var route = publicPath == "/models/openai-live/v1/sessions" && path == "/sessions" && method == "POST" ? "liveCreate"
      : publicPath == "/models/openai-realtime/v1/calls" && path == "/calls" && method == "POST" ? "realtimeCreate"
      : (method == "POST" || method == "GET" || method == "DELETE")
        && (publicPath == "/tools/pii-v1-mcp/mcp" || publicPath == "/tools/pii-v1-mcp/mcp/") ? "piiMcp" : "none";
    if (route == "none") { return result.ToString(Newtonsoft.Json.Formatting.None); }
    var kind = "";
    try {
      var settings = JObject.Parse((string)context.Variables["gatewayAuditSettings"]);
      kind = (string)settings["operationConstraints"]?[route == "piiMcp" ? "pii_redact_text" : operation]?["kind"];
    } catch { return result.ToString(Newtonsoft.Json.Formatting.None); }
    if ((route == "liveCreate" && kind != "liveCreate") || (route == "realtimeCreate" && kind != "realtimeCreate")
        || (route == "piiMcp" && kind != "pii")) { return result.ToString(Newtonsoft.Json.Formatting.None); }
    result["route"] = route;
    result["httpMethod"] = method;
    var mode = "observe";
    try {
      if (context.Variables.ContainsKey("gatewayQueryGuardModes")) {
        var modes = JObject.Parse((string)context.Variables["gatewayQueryGuardModes"]);
        var configured = modes[route];
        if (configured != null) {
          if (configured.Type != JTokenType.String) { throw new Exception("Invalid query guard mode"); }
          mode = (string)configured;
        }
      }
      if (mode != "observe" && mode != "reject") { throw new Exception("Invalid query guard mode"); }
      result["mode"] = mode;
    } catch {
      result["mode"] = "unknown"; result["allowed"] = false; result["status"] = 503;
      return result.ToString(Newtonsoft.Json.Formatting.None);
    }
    try {
      var query = context.Request.Url.Query;
      if (query == null) { throw new Exception("Query shape unavailable"); }
      var present = query.Count > 0;
      var count = 0;
      var duplicate = false;
      foreach (var argument in query) {
        var length = argument.Value == null ? 1 : Math.Max(1, argument.Value.Length);
        count = Math.Min(5, count + Math.Min(5, length));
        duplicate = duplicate || length > 1;
      }
      result["presence"] = present ? "present" : "none";
      result["countBucket"] = count == 0 ? "0" : count == 1 ? "1" : count < 5 ? "2-4" : "5+";
      result["duplicates"] = duplicate ? "yes" : "no";
      result["allowed"] = mode != "reject" || !present;
      result["status"] = (bool)result["allowed"] ? 0 : 400;
    } catch {
      /* 観測失敗はunknownとし、queryなしの正常利用の証拠にしません。 */
      result["allowed"] = mode != "reject"; result["status"] = mode == "reject" ? 400 : 0;
    }
    return result.ToString(Newtonsoft.Json.Formatting.None);
  }
